<?php /** @var array $rows @var array $f @var int $total @var int $page @var int $per */
$sev = static fn(string $s) => '<span class="badge ' . ($s === 'high' ? 'danger' : ($s === 'medium' ? 'warn' : '')) . '">' . e(t('enum.sev.' . $s)) . '</span>'; ?>
<div class="page-head"><div><h1><?= icon('alert') ?> <?= e(t('sha.events')) ?></h1><p class="sub"><?= e(t('sha.events_hint')) ?> · <?= e(t('common.total_n', ['n' => $total])) ?></p></div>
  <div class="actions"><a class="btn secondary" href="<?= e(url('sharia')) ?>"><?= e(t('common.back')) ?></a><?php if (can('sharia.report')): ?><a class="btn gold" href="<?= e(url('sharia/events/new')) ?>"><?= e(t('sha.event_new')) ?></a><?php endif; ?></div></div>
<form method="get" action="<?= e(url('sharia/events')) ?>" class="card filters">
  <?= ff('select', 'status', 'sha.e_status', $f['status'], ['options' => opts(['reported', 'under_review', 'decided', 'closed'], fn($x) => t('enum.sevent.' . $x), null), 'blank_label' => 'common.all']) ?>
  <?= ff('select', 'severity', 'sha.e_severity', $f['severity'], ['options' => opts(\App\Controllers\ShariaController::SEVERITIES, fn($x) => t('enum.sev.' . $x), null), 'blank_label' => 'common.all']) ?>
  <div class="field"><label class="check"><input type="checkbox" name="open" value="1"<?= checked($f['open']) ?>> <?= e(t('sha.open_only')) ?></label></div>
  <div class="field"><label class="check"><input type="checkbox" name="purification" value="1"<?= checked($f['purification']) ?>> <?= e(t('sha.stat_purify')) ?></label></div>
  <div class="field actions"><button class="btn" type="submit"><?= e(t('common.filter')) ?></button><a class="btn secondary" href="<?= e(url('sharia/events')) ?>"><?= e(t('common.reset')) ?></a></div></form>
<div class="table-wrap"><table class="data"><thead><tr><th><?= e(t('sha.e_code')) ?></th><th><?= e(t('sha.e_title')) ?></th><th><?= e(t('sha.e_dept')) ?></th><th><?= e(t('sha.e_detected')) ?></th><th><?= e(t('sha.e_severity')) ?></th><th><?= e(t('sha.e_status')) ?></th><th class="num"><?= e(t('sha.e_income')) ?></th></tr></thead><tbody>
<?php if (!$rows): ?><tr><td colspan="7" class="empty"><?= e(t('common.no_results')) ?></td></tr><?php endif; ?>
<?php foreach ($rows as $e): ?><tr><td class="nowrap"><a href="<?= e(url('sharia/events/' . $e['id'])) ?>"><?= e($e['code']) ?></a></td><td><a href="<?= e(url('sharia/events/' . $e['id'])) ?>"><?= e($e['title']) ?></a><?= $e['escalated_at'] ? ' <span class="badge danger">' . e(t('sha.escalated')) . '</span>' : '' ?></td><td><?= e(lname($e, 'dept')) ?></td><td class="nowrap"><?= e(fdate($e['detected_on'])) ?></td><td><?= $sev($e['severity']) ?></td><td><?= e(t('enum.sevent.' . $e['status'])) ?><?= $e['purification_status'] === 'pending' ? ' <span class="badge warn">' . e(t('sha.purify_pending')) . '</span>' : '' ?></td><td class="num"><?= (float)$e['impermissible_income'] > 0 ? e(money($e['impermissible_income'])) : '—' ?></td></tr><?php endforeach; ?></tbody></table></div>
<?= pager($total, $page, $per) ?>
